-- CinemaScope Supabase SQL
-- Run this in the Supabase SQL Editor
-- SESSION 1


-- ============================================================
-- PROFILES (for auth)
-- ============================================================
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'viewer',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can view own profile" ON public.profiles
  FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Users can update own profile" ON public.profiles
  FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "Service can insert profile" ON public.profiles
  FOR INSERT WITH CHECK (auth.uid() = id);

-- Function to auto-create profile on signup
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  VALUES (NEW.id, NEW.email, 'viewer')
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


-- ============================================================
-- DIM_GENRE
-- ============================================================
CREATE TABLE IF NOT EXISTS public.dim_genre (
  genre_id SERIAL PRIMARY KEY,
  genre_name TEXT NOT NULL
);

ALTER TABLE public.dim_genre ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read dim_genre" ON public.dim_genre FOR SELECT USING (true);



-- ============================================================
-- DIM_DIRECTOR
-- ============================================================
CREATE TABLE IF NOT EXISTS public.dim_director (
  director_id SERIAL PRIMARY KEY,
  director_name TEXT NOT NULL
);

ALTER TABLE public.dim_director ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read dim_director" ON public.dim_director FOR SELECT USING (true);








-- ============================================================
-- DIM_TIME
-- ============================================================
CREATE TABLE IF NOT EXISTS public.dim_time (
  time_id SERIAL PRIMARY KEY,
  year INTEGER NOT NULL,
  decade TEXT,
  era TEXT
);

ALTER TABLE public.dim_time ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read dim_time" ON public.dim_time FOR SELECT USING (true);



-- ============================================================
-- FACT_MOVIES
-- ============================================================
CREATE TABLE IF NOT EXISTS public.fact_movies (
  movie_id SERIAL PRIMARY KEY,
  series_title TEXT NOT NULL,
  released_year INTEGER,
  certificate TEXT,
  runtime_min NUMERIC,
  genre TEXT,
  imdb_rating NUMERIC,
  meta_score NUMERIC,
  no_of_votes INTEGER,
  gross NUMERIC,
  director_name TEXT,
  era TEXT,
  rating_category TEXT,
  overview TEXT
);

ALTER TABLE public.fact_movies ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read fact_movies" ON public.fact_movies FOR SELECT USING (true);






















-- Reset sequences
SELECT setval('public.dim_genre_genre_id_seq', (SELECT MAX(genre_id) FROM public.dim_genre));
SELECT setval('public.dim_director_director_id_seq', (SELECT MAX(director_id) FROM public.dim_director));
SELECT setval('public.dim_time_time_id_seq', (SELECT MAX(time_id) FROM public.dim_time));
SELECT setval('public.fact_movies_movie_id_seq', (SELECT MAX(movie_id) FROM public.fact_movies));

-- ============================================================
-- WATCHLIST (user saved films)
-- ============================================================
CREATE TABLE IF NOT EXISTS public.watchlist (
  id          BIGSERIAL PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  movie_id    INTEGER NOT NULL REFERENCES public.fact_movies(movie_id) ON DELETE CASCADE,
  added_at    TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (user_id, movie_id)
);

ALTER TABLE public.watchlist ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own watchlist" ON public.watchlist
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own watchlist" ON public.watchlist
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can delete own watchlist" ON public.watchlist
  FOR DELETE USING (auth.uid() = user_id);

-- Index for fast lookups
CREATE INDEX IF NOT EXISTS idx_watchlist_user ON public.watchlist(user_id);

-- SESSION 2
-- ============================================================
-- CinemaScope Admin Update SQL
-- Jalankan di Supabase SQL Editor (sekali)
-- ============================================================

-- 1) Helper function: cek apakah user login adalah admin
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND lower(p.role) = 'admin'
  );
$$;

-- 2) FACT_MOVIES: izinkan admin CRUD
DROP POLICY IF EXISTS "Admins can insert fact_movies" ON public.fact_movies;
DROP POLICY IF EXISTS "Admins can update fact_movies" ON public.fact_movies;
DROP POLICY IF EXISTS "Admins can delete fact_movies" ON public.fact_movies;

CREATE POLICY "Admins can insert fact_movies"
ON public.fact_movies
FOR INSERT
WITH CHECK (public.is_admin());

CREATE POLICY "Admins can update fact_movies"
ON public.fact_movies
FOR UPDATE
USING (public.is_admin())
WITH CHECK (public.is_admin());

CREATE POLICY "Admins can delete fact_movies"
ON public.fact_movies
FOR DELETE
USING (public.is_admin());

-- 3) PROFILES: izinkan admin lihat semua user + update role user
-- (policy lama "Users can view own profile" dan "Users can update own profile"
-- tetap aman dipakai bersamaan)
DROP POLICY IF EXISTS "Admins can view all profiles" ON public.profiles;
DROP POLICY IF EXISTS "Admins can update all profiles" ON public.profiles;

CREATE POLICY "Admins can view all profiles"
ON public.profiles
FOR SELECT
USING (public.is_admin());

CREATE POLICY "Admins can update all profiles"
ON public.profiles
FOR UPDATE
USING (public.is_admin())
WITH CHECK (public.is_admin());

-- 4) (Opsional tapi disarankan) validasi nilai role agar konsisten
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'profiles_role_check'
  ) THEN
    ALTER TABLE public.profiles
      ADD CONSTRAINT profiles_role_check
      CHECK (lower(role) IN ('admin', 'viewer'));
  END IF;
END $$;

-- 5) Jadikan akun kamu admin (ganti email kamu)
-- UPDATE public.profiles
-- SET role = 'admin'
-- WHERE email = 'emailkamu@example.com';

-- 6) Verifikasi cepat
-- SELECT id, email, role, created_at FROM public.profiles ORDER BY created_at DESC;

-- SESSION 3
-- ============================================================
-- CinemaScope Admin Policy Bundle (ONE-RUN)
-- Jalankan sekali di Supabase SQL Editor
-- ============================================================

BEGIN;

-- 1) Helper function: cek user login adalah admin
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND lower(p.role) = 'admin'
  );
$$;

-- 2) Profiles: admin bisa lihat semua user
DROP POLICY IF EXISTS "Admins can view all profiles" ON public.profiles;
CREATE POLICY "Admins can view all profiles"
ON public.profiles
FOR SELECT
USING (public.is_admin());

-- 3) Profiles: admin bisa update semua user
DROP POLICY IF EXISTS "Admins can update all profiles" ON public.profiles;
CREATE POLICY "Admins can update all profiles"
ON public.profiles
FOR UPDATE
USING (public.is_admin())
WITH CHECK (public.is_admin());

-- 4) Profiles: admin bisa delete semua user
DROP POLICY IF EXISTS "Admins can delete all profiles" ON public.profiles;
CREATE POLICY "Admins can delete all profiles"
ON public.profiles
FOR DELETE
USING (public.is_admin());

-- 5) (Opsional disarankan) pastikan nilai role valid
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'profiles_role_check'
  ) THEN
    ALTER TABLE public.profiles
      ADD CONSTRAINT profiles_role_check
      CHECK (lower(role) IN ('admin', 'viewer'));
  END IF;
END $$;

COMMIT;

-- ============================================================
-- Verifikasi cepat
-- ============================================================
SELECT policyname, cmd, permissive, qual, with_check
FROM pg_policies
WHERE schemaname = 'public'
  AND tablename = 'profiles'
ORDER BY policyname;
-- ============================================================
-- VIEWER MOVIE FEEDBACK (user personal rating/metascore)
-- ============================================================
CREATE TABLE IF NOT EXISTS public.viewer_movie_feedback (
  id                BIGSERIAL PRIMARY KEY,
  user_id           UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  movie_id          INTEGER NOT NULL REFERENCES public.fact_movies(movie_id) ON DELETE CASCADE,
  viewer_rating     NUMERIC(3,1) NOT NULL,
  viewer_metascore  INTEGER NOT NULL,
  created_at        TIMESTAMPTZ DEFAULT NOW(),
  updated_at        TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (user_id, movie_id),
  CONSTRAINT viewer_rating_range CHECK (viewer_rating >= 0 AND viewer_rating <= 10),
  CONSTRAINT viewer_metascore_range CHECK (viewer_metascore >= 0 AND viewer_metascore <= 100)
);

ALTER TABLE public.viewer_movie_feedback ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view own viewer feedback" ON public.viewer_movie_feedback;
CREATE POLICY "Users can view own viewer feedback" ON public.viewer_movie_feedback
  FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can insert own viewer feedback" ON public.viewer_movie_feedback;
CREATE POLICY "Users can insert own viewer feedback" ON public.viewer_movie_feedback
  FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can update own viewer feedback" ON public.viewer_movie_feedback;
CREATE POLICY "Users can update own viewer feedback" ON public.viewer_movie_feedback
  FOR UPDATE USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users can delete own viewer feedback" ON public.viewer_movie_feedback;
CREATE POLICY "Users can delete own viewer feedback" ON public.viewer_movie_feedback
  FOR DELETE USING (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS idx_viewer_feedback_user ON public.viewer_movie_feedback(user_id);
CREATE INDEX IF NOT EXISTS idx_viewer_feedback_movie ON public.viewer_movie_feedback(movie_id);
